span:not(.ic){display:block;color:rgba(255,255,255,.72);font-size:15px;line-height:1.5}
.aic em{font-style:normal;display:inline-block;margin-top:12px;font-size:12px;font-family:var(--disp);font-weight:700;padding:5px 10px;border-radius:999px;background:rgba(38,194,129,.18);color:#7BE8B5}
.aic em.soon{background:rgba(255,199,0,.15);color:var(--y)}
.ai .aiend{margin-top:30px;color:rgba(255,255,255,.7);font-size:15px}
@media (max-width:1100px){.aig{grid-template-columns:1fr 1fr}}
@media (max-width:600px){.aig{grid-template-columns:1fr}.ai{border-radius:26px}}

/* свои инструменты */
.tools{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
.tl{background:#fff;border:1px solid var(--line);border-radius:22px;overflow:hidden;display:flex;flex-direction:column;text-align:start;transition:transform .35s cubic-bezier(.2,.8,.2,1),box-shadow .35s}
.tl:hover{transform:translateY(-4px);box-shadow:0 24px 50px rgba(30,25,15,.12)}
.tl .im{height:230px;overflow:hidden;background:#EFEBE2}
.tl .im img{width:100%;height:100%;object-fit:cover;object-position:top;display:block}
.tl .tx{padding:18px 20px 20px;display:flex;flex-direction:column;gap:6px;flex:1}
.tl .tag{font-family:var(--disp);font-size:11px;font-weight:700;color:var(--mut)}
.tl b{font-family:var(--disp);font-size:18px;letter-spacing:-.02em}
.tl span{color:#3a3731;font-size:15px;line-height:1.45}
.tl u{text-decoration:none;margin-top:auto;padding-top:8px;font-weight:700;font-size:14px;border-bottom:2px solid var(--y);align-self:flex-start}
@media (max-width:1100px){.tools{grid-template-columns:1fr 1fr}}
@media (max-width:600px){.tools{grid-template-columns:1fr}}
.grp-l{position:absolute;font-family:var(--disp);font-weight:800;font-size:22px;letter-spacing:-.03em;color:var(--ink);display:flex;align-items:center;gap:10px}
.grp-l i{font-style:normal;font-size:12px;font-weight:700;background:var(--ink);color:#fff;border-radius:999px;padding:4px 10px}
.sto dd ul{margin:0;padding-inline-start:20px;display:grid;gap:4px}

/* курсор */
.cur{position:fixed;left:0;top:0;z-index:100;pointer-events:none;width:12px;height:12px;margin:-6px 0 0 -6px;border-radius:50%;background:var(--ink);transition:width .3s cubic-bezier(.2,.8,.2,1),height .3s cubic-bezier(.2,.8,.2,1),margin .3s cubic-bezier(.2,.8,.2,1),background .3s;display:grid;place-items:center;color:var(--ink);font-family:var(--disp);font-weight:700;font-size:12px}
.cur span{opacity:0;transition:opacity .2s}
.cur.big2{width:78px;height:78px;margin:-39px 0 0 -39px;background:var(--y)}
.cur.big2 span{opacity:1}
body.modal .cur{display:none}
@media (hover:none),(pointer:coarse){.cur{display:none}}

@media (prefers-reduced-motion:reduce){.glow,.card .g2,.kick .dot,.scrollhint i{animation:none}html{scroll-behavior:auto}}
